"""Stage 96: the resource catalogue (docs/62, generated by tools/analyze_resources_docs.py) is current, the facts it states hold (79 regions, 2,246 bytes, the 85-entry blob, the font's source, the ignored status of the derived and original
files), every original material is in the manifest and verifies, and the C sources hold no byte of the ROM's data."""
import hashlib
import os
import re
import subprocess
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_resources_docs as R  # noqa: E402

DOC = os.path.join(ROOT, "docs", "62-resources-catalogue.md")


class Resources(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.f = R.facts()

    def test_the_chapter_is_current(self):
        with open(DOC, encoding="utf-8", newline="") as fh:
            have = fh.read().replace("\r\n", "\n")
        self.assertEqual(have, R.doc(), "regenerate: python -I tools/analyze_resources_docs.py --doc docs/62-resources-catalogue.md")

    def test_the_headline_facts(self):
        P = self.f["P"]
        self.assertEqual((len(P["regions"]), sum(r["size"] for r in P["regions"])), (79, 2246))
        self.assertEqual((len(self.f["entries"]), len(self.f["blob"])), (85, 9392))
        self.assertEqual((len(P["sprites"]["shapes"]), len(P["text"]["strings"])), (21, 8))
        self.assertEqual((P["charsets"]["game"]["glyphs"], P["charsets"]["title"]["glyphs"]), (101, 24))
        self.assertEqual((P["maze"]["rows"], P["maze"]["cols"], P["maze"]["dots"], len(P["maze"]["power_pellets"])), (23, 40, 256, 4))

    def test_every_original_material_is_in_the_manifest_and_verifies(self):
        rows = R.manifest_rows()
        names = {p for p, s, h in rows}
        files = {"original/" + n for n in os.listdir(os.path.join(ROOT, "original")) if os.path.isfile(os.path.join(ROOT, "original", n)) and n != "README.md" and n not in R.UNUSED_ORIGINALS}
        self.assertEqual(names, files, "a file of original/ that is not in docs/original-manifest.txt (or the other way round); only R.UNUSED_ORIGINALS may be outside it")
        self.assertFalse(any("PAL" in n for n in names), "the PAL OS ROM is not a project material (2026-11-23)")
        for p, size, sha in rows:
            with open(os.path.join(ROOT, *p.split("/")), "rb") as fh:
                data = fh.read()
            self.assertEqual((len(data), hashlib.sha256(data).hexdigest()), (size, sha), p)

    def test_the_font_is_the_one_in_third_party(self):
        s = self.f["P"]["font"]["source"]
        with open(os.path.join(ROOT, *s["file"].split("/")), "rb") as fh:
            self.assertEqual(hashlib.sha256(fh.read()).hexdigest(), s["sha256"])
        self.assertTrue(os.path.exists(os.path.join(ROOT, "third-party", "EightBit-Atari-Fonts", "OFL.txt")))

    def test_the_ignored_status_agrees_with_git(self):
        paths = ["original/Pac-Man.rom", "resources/pack/assets.json", "build/x", "analysis/x.png", "analysis/x.wav", "analysis/raw-logs/x.txt", "analysis/evidence-behaviour-summary.txt", "src/c/core/world.h", "third-party/README.md"]
        try:
            for p in paths:
                r = subprocess.run(["git", "check-ignore", "-q", p], cwd=ROOT, capture_output=True)
                self.assertEqual(r.returncode == 0, R.ignored(p), p)
        except FileNotFoundError:
            self.skipTest("no git")

    def test_the_owners_personal_notes_are_never_part_of_anything(self):
        """the owner's decision of 2026-11-23: `Personal notes.txt` is in no commit, build, release or archive: Git ignores it and the clean-copy check does not copy it"""
        self.assertTrue(R.ignored("Personal notes.txt"))
        try:
            r = subprocess.run(["git", "ls-files", "-co", "--exclude-standard"], cwd=ROOT, capture_output=True, text=True)
            self.assertNotIn("Personal notes.txt", r.stdout.splitlines())
        except FileNotFoundError:
            self.skipTest("no git")
        with open(os.path.join(ROOT, "tools", "check_clean_build.py"), encoding="utf-8") as fh:
            self.assertIn("Personal notes.txt", fh.read())

    def test_the_c_sources_hold_no_table_of_the_rom(self):
        """a run of 12 or more hex bytes in a row in a hand-written source would be a table copied from the ROM; the generated files hold none either (layout only, the font's glyphs excepted)"""
        pat = re.compile(r"(0x[0-9A-Fa-f]{2},\s*){12,}")
        bad = []
        for dp, _, fs in os.walk(os.path.join(ROOT, "src", "c")):
            for f in fs:
                if f.endswith((".c", ".h")) and f not in ("rom_layout.c", "palette.c"):
                    with open(os.path.join(dp, f), encoding="utf-8") as fh:
                        if pat.search(fh.read()):
                            bad.append(f)
        self.assertEqual(bad, [])


if __name__ == "__main__":
    unittest.main()
